    "dqx:regex_match": ("regex_match", frozenset({"column", "regex"})),
    "dqx:is_not_less_than": ("is_not_less_than", frozenset({"column", "limit"})),
    "dqx:is_not_greater_than": ("is_not_greater_than", frozenset({"column", "limit"})),
